//! A problem for an external code, and the errors of that code's output (Phase 6 T9,
//! C6.8: the FMM3D comparison, docs/design/optimisation.md §8.1).
//!
//! [`write_problem`] writes the points and charges of a `scaling` workload
//! (`nd_fmm_validate::scaling::Workload`: every point and charge generated by index from
//! `scaling::SEED`, the problems of the `scaling` example and of `tools/scaling/run.sh`)
//! to one binary file, with the sampled targets of that harness's errors
//! (`Workload::sample`) and the f64 direct sum at them. An external program reads the
//! points and charges, evaluates φ and ∇φ, and writes them at the sampled targets
//! ([`write_output`]'s format); [`check_output`] measures that output against the direct
//! sum with the error metrics of the `scaling` harness. Both codes are then measured on
//! the same points and charges, at the same targets, against the same direct sum
//! (`tools/fmm3d/README.md`).
//!
//! # The problem file
//!
//! Little-endian, no padding; `u64` counts and indices, `f64` values:
//!
//! | part | type | contents |
//! | --- | --- | --- |
//! | magic | 8 bytes | [`PROBLEM_MAGIC`] |
//! | header | 5 × `u64` | N, the charge vectors m, the sampled targets s, the seed, the distribution ([`distribution_code`]) |
//! | points | N × 3 `f64` | x, y, z of point i, for i = 0 … N − 1 (FMM3D's `source(3, N)`) |
//! | charges | N × m `f64` | the charges of point i in vectors 0 … m − 1, point after point (FMM3D's `charge(m, N)`) |
//! | sample | s × `u64` | the indices of the sampled targets, from 0, in `Workload::sample`'s order |
//! | reference | s × m × 4 `f64` | at sampled target j, for vector k: φ, ∂φ/∂x, ∂φ/∂y, ∂φ/∂z |
//!
//! The reference is `nd_fmm_validate::fmm_accuracy::Oracle`: `nd_fmm_ref::p2p::direct_sum`
//! in f64 over every point (the target itself skipped), divided by 4π, the potential
//! 1/(4π r) of CONVENTIONS §3.1, as the FMM reports it and the `scaling` harness's errors
//! compare. Its gradient is ∇φ, with ∇(1/r) = −(x − y)/|x − y|³.
//!
//! # The output file
//!
//! | part | type | contents |
//! | --- | --- | --- |
//! | magic | 8 bytes | [`OUTPUT_MAGIC`] |
//! | header | 2 × `u64` | m, s (equal to the problem's) |
//! | values | s × m × 4 `f64` | as the reference: φ and ∇φ at sampled target j for vector k, in the normalisation of CONVENTIONS §3.1 |
//!
//! # The full output file
//!
//! The same at every point (the cross-check of two codes' outputs, not only their errors):
//! [`FULL_MAGIC`], then m and N as `u64`, then N × m × 4 `f64`, φ and ∇φ at point i for
//! vector k. [`evaluate_problem`] writes ours ([`write_full_output`]), the FMM3D driver
//! its own; [`check_output`] takes either kind (a full file at the problem's sampled
//! targets), and [`compare_outputs`] measures one full output against another over every
//! point.

use std::fs::File;
use std::io::{self, BufReader, BufWriter, Read, Seek, SeekFrom, Write};
use std::path::{Path, PathBuf};
use std::time::Instant;

use mpi::traits::CommunicatorCollectives;
use nd_fmm_exec::fmm::FmmBuilder;
use nd_fmm_validate::fmm_accuracy::{self, Distribution, Oracle};
use nd_fmm_validate::metrics::{ErrorAccumulator, ErrorNorms};
use nd_fmm_validate::scaling::Workload;

/// The first eight bytes of a problem file.
pub const PROBLEM_MAGIC: [u8; 8] = *b"NDFMMPB1";

/// The first eight bytes of an output file.
pub const OUTPUT_MAGIC: [u8; 8] = *b"NDFMMOU1";

/// The first eight bytes of a full output file (every point).
pub const FULL_MAGIC: [u8; 8] = *b"NDFMMFU1";

/// The default charge vectors of a problem: the 8 of the error measures of
/// laplace-fmm-plan §8.2.
pub const DEFAULT_VECTORS: usize = 8;

/// The bytes before the points: the magic and five `u64`.
const HEADER_BYTES: u64 = 8 + 5 * 8;

/// What `--write-problem` writes.
#[derive(Clone, Debug, PartialEq)]
pub struct ProblemSpec {
    /// The file.
    pub file: PathBuf,
    /// The points and charges (`Workload::new`: the `scaling` example's seed).
    pub workload: Workload,
    /// The charge vectors, at least 1.
    pub vectors: usize,
    /// The sampled targets of the errors, at most N.
    pub sampled: usize,
    /// Threads of the direct sum; every core if `None`.
    pub threads: Option<usize>,
}

/// What [`write_problem`] did.
#[derive(Clone, Debug, PartialEq)]
pub struct Written {
    /// The bytes written.
    pub bytes: u64,
    /// The seconds of the direct sum at the sampled targets.
    pub reference_seconds: f64,
    /// The threads of the direct sum.
    pub threads: usize,
}

/// The number of a distribution in the problem file: 0 cube, 1 sphere, 2 Plummer,
/// 3 clusters.
pub fn distribution_code(distribution: Distribution) -> u64 {
    match distribution {
        Distribution::Cube => 0,
        Distribution::Sphere => 1,
        Distribution::Plummer => 2,
        Distribution::Clusters => 3,
    }
}

/// The distribution of a [`distribution_code`].
fn distribution_of(code: u64) -> Option<Distribution> {
    Distribution::ALL
        .into_iter()
        .find(|&d| distribution_code(d) == code)
}

/// Writes the problem file of `spec` (module documentation), the reference computed on
/// `spec.threads` threads (each sampled target on one thread, so the values do not depend
/// on the thread count).
///
/// # Errors
///
/// An I/O error of the file.
///
/// # Panics
///
/// If `spec.vectors` is 0 or `spec.sampled` exceeds N.
pub fn write_problem(spec: &ProblemSpec) -> io::Result<Written> {
    assert!(spec.vectors > 0, "a problem needs a charge vector");
    let workload = &spec.workload;
    let (n, m) = (workload.n, spec.vectors);
    let problem = fmm_accuracy::Problem {
        points: (0..n).map(|i| workload.point(i)).collect(),
        sample: workload.sample(spec.sampled),
        charges: (0..m)
            .map(|k| (0..n).map(|i| workload.charge(k, i)).collect())
            .collect(),
    };
    let targets = problem.sampled_points();
    let threads = spec
        .threads
        .unwrap_or_else(|| std::thread::available_parallelism().map_or(1, std::num::NonZero::get))
        .clamp(1, targets.len().max(1));
    let start = Instant::now();
    let reference = reference(&problem, &targets, threads);
    let reference_seconds = start.elapsed().as_secs_f64();

    let mut file = BufWriter::new(File::create(&spec.file)?);
    file.write_all(&PROBLEM_MAGIC)?;
    let header = [
        n as u64,
        m as u64,
        problem.sample.len() as u64,
        workload.seed,
        distribution_code(workload.distribution),
    ];
    for value in header {
        file.write_all(&value.to_le_bytes())?;
    }
    for point in &problem.points {
        write_f64s(&mut file, point)?;
    }
    for i in 0..n {
        for vector in &problem.charges {
            file.write_all(&vector[i].to_le_bytes())?;
        }
    }
    for &i in &problem.sample {
        file.write_all(&(i as u64).to_le_bytes())?;
    }
    write_f64s(&mut file, &reference)?;
    file.flush()?;
    let bytes = file.get_ref().metadata()?.len();
    Ok(Written {
        bytes,
        reference_seconds,
        threads,
    })
}

/// φ and ∇φ of every vector at every target, target after target, vector after vector:
/// the oracle of `problem` (its own charges), the targets split into contiguous blocks
/// over `threads`.
fn reference(problem: &fmm_accuracy::Problem, targets: &[[f64; 3]], threads: usize) -> Vec<f64> {
    let m = problem.charges.len();
    let mut values = vec![0.0; targets.len() * m * 4];
    if targets.is_empty() {
        return values;
    }
    let per_thread = targets.len().div_ceil(threads);
    std::thread::scope(|scope| {
        for (block, out) in targets
            .chunks(per_thread)
            .zip(values.chunks_mut(per_thread * m * 4))
        {
            scope.spawn(move || {
                let oracle = Oracle::of_targets(problem, &problem.charges, block);
                for (k, (phi, grad)) in oracle.potential.iter().zip(&oracle.gradient).enumerate() {
                    for (j, (p, g)) in phi.iter().zip(grad).enumerate() {
                        let at = (j * m + k) * 4;
                        out[at] = *p;
                        out[at + 1..at + 4].copy_from_slice(g);
                    }
                }
            });
        }
    });
    values
}

/// The header of a problem file.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ProblemHeader {
    /// The points and charges.
    pub workload: Workload,
    /// The charge vectors.
    pub vectors: usize,
    /// The sampled targets.
    pub sampled: usize,
}

/// Reads the header of a problem file.
///
/// # Errors
///
/// An I/O error, or `InvalidData` for a file that does not start with
/// [`PROBLEM_MAGIC`] or names no distribution.
pub fn read_header(reader: &mut impl Read) -> io::Result<ProblemHeader> {
    let mut magic = [0u8; 8];
    reader.read_exact(&mut magic)?;
    if magic != PROBLEM_MAGIC {
        return Err(invalid("not a problem file (its magic is wrong)"));
    }
    let [n, vectors, sampled, seed, code] = read_u64s::<5>(reader)?;
    let distribution =
        distribution_of(code).ok_or_else(|| invalid(&format!("distribution {code}")))?;
    Ok(ProblemHeader {
        workload: Workload {
            distribution,
            n: n as usize,
            seed,
        },
        vectors: vectors as usize,
        sampled: sampled as usize,
    })
}

/// The header and the reference of a problem file (φ and ∇φ per sampled target and
/// vector, as [`write_output`] takes them).
///
/// # Errors
///
/// As [`read_header`], or a file shorter than its header says.
pub fn read_reference(problem: &Path) -> io::Result<(ProblemHeader, Vec<f64>)> {
    let mut file = BufReader::new(File::open(problem)?);
    let header = read_header(&mut file)?;
    let (n, m, s) = (
        header.workload.n as u64,
        header.vectors as u64,
        header.sampled as u64,
    );
    file.seek(SeekFrom::Start(HEADER_BYTES + 8 * (3 * n + m * n + s)))?;
    let values = read_f64s(&mut file, (s * m * 4) as usize)?;
    Ok((header, values))
}

/// The contents of a problem file but the reference: the header, the points, the charge
/// vectors (vector after vector) and the sampled targets' indices.
#[derive(Clone, Debug, PartialEq)]
pub struct ProblemData {
    /// The header.
    pub header: ProblemHeader,
    /// The points, sources and targets alike.
    pub points: Vec<[f64; 3]>,
    /// The charges, `charges[k][i]` of point i in vector k.
    pub charges: Vec<Vec<f64>>,
    /// The sampled targets' indices.
    pub sample: Vec<usize>,
}

/// Reads a problem file's points, charges and sampled targets.
///
/// # Errors
///
/// As [`read_header`], or a file shorter than its header says.
pub fn read_problem(problem: &Path) -> io::Result<ProblemData> {
    let mut file = BufReader::new(File::open(problem)?);
    let header = read_header(&mut file)?;
    let (n, m, s) = (header.workload.n, header.vectors, header.sampled);
    let flat = read_f64s(&mut file, 3 * n)?;
    let points = flat.as_chunks::<3>().0.to_vec();
    let point_major = read_f64s(&mut file, m * n)?;
    let charges = (0..m)
        .map(|k| (0..n).map(|i| point_major[i * m + k]).collect())
        .collect();
    let mut sample = Vec::with_capacity(s);
    for _ in 0..s {
        sample.push(read_u64s::<1>(&mut file)?[0] as usize);
    }
    Ok(ProblemData {
        header,
        points,
        charges,
        sample,
    })
}

/// Our FMM on a problem file (Phase 6 T9's cross-check): `builder`'s FMM over the problem's
/// points in index order on `comm` (one rank), every charge vector evaluated by
/// `Fmm::evaluate`, φ and ∇φ at every point in the full output layout (module
/// documentation), and the seconds of the evaluations.
///
/// # Errors
///
/// A message for an unreadable problem file, an FMM that does not build or evaluate, or
/// one built without gradients.
pub fn evaluate_problem<C: CommunicatorCollectives>(
    problem: &Path,
    builder: &FmmBuilder<f64>,
    comm: &C,
) -> Result<(ProblemHeader, Vec<f64>, f64), String> {
    let data = read_problem(problem).map_err(|e| format!("{}: {e}", problem.display()))?;
    let (n, m) = (data.points.len(), data.charges.len());
    let mut fmm = builder
        .build(&data.points, &data.points, comm)
        .map_err(|e| format!("the FMM does not build: {e}"))?;
    let mut values = vec![0.0; n * m * 4];
    let mut seconds = 0.0;
    for (k, charges) in data.charges.iter().enumerate() {
        let start = Instant::now();
        let output = fmm
            .evaluate(charges)
            .map_err(|e| format!("the FMM does not evaluate: {e}"))?;
        seconds += start.elapsed().as_secs_f64();
        let gradient = output
            .gradient
            .ok_or("the FMM was built without gradients")?;
        for (i, (phi, g)) in output.potential.iter().zip(&gradient).enumerate() {
            let at = (i * m + k) * 4;
            values[at] = *phi;
            values[at + 1..at + 4].copy_from_slice(g);
        }
    }
    Ok((data.header, values, seconds))
}

/// Writes a full output file: φ and ∇φ at every point, N × m × 4 values (module
/// documentation).
///
/// # Errors
///
/// An I/O error of the file.
///
/// # Panics
///
/// If `values.len() != points * vectors * 4`.
pub fn write_full_output(
    path: &Path,
    vectors: usize,
    points: usize,
    values: &[f64],
) -> io::Result<()> {
    assert_eq!(values.len(), points * vectors * 4, "N × m × 4 values");
    let mut file = BufWriter::new(File::create(path)?);
    file.write_all(&FULL_MAGIC)?;
    for value in [vectors as u64, points as u64] {
        file.write_all(&value.to_le_bytes())?;
    }
    write_f64s(&mut file, values)?;
    file.flush()
}

/// The vectors, the points and the values of a full output file.
fn read_full(path: &Path) -> io::Result<(usize, usize, Vec<f64>)> {
    let mut file = BufReader::new(File::open(path)?);
    let mut magic = [0u8; 8];
    file.read_exact(&mut magic)?;
    if magic != FULL_MAGIC {
        return Err(invalid("not a full output file (its magic is wrong)"));
    }
    let [m, n] = read_u64s::<2>(&mut file)?;
    let values = read_f64s(&mut file, (m * n * 4) as usize)?;
    Ok((m as usize, n as usize, values))
}

/// The difference of the full output `other` from the full output `reference` over every
/// point, as [`OutputErrors`] (`sampled` is then N): per vector the relative L2 and max
/// differences of φ and ∇φ, the root mean square over the vectors.
///
/// # Errors
///
/// An I/O error, a file that is not a full output, or two of different shapes
/// (`InvalidData`).
pub fn compare_outputs(reference: &Path, other: &Path) -> io::Result<OutputErrors> {
    let (m, n, exact) = read_full(reference)?;
    let (m2, n2, values) = read_full(other)?;
    if (m, n) != (m2, n2) {
        return Err(invalid(&format!(
            "{} has {m2} vectors at {n2} points, {} {m} at {n}",
            other.display(),
            reference.display()
        )));
    }
    Ok(errors(m, n, &values, &exact))
}

/// The line of `--compare` on stdout for one pair: the fields of [`errors_line`], the
/// differences over every point.
pub fn difference_line(reference: &Path, other: &Path, difference: &OutputErrors) -> String {
    format!(
        "difference: file={} against={} vectors={} points={} phi_l2={:.3e} phi_max={:.3e} \
         grad_l2={:.3e} grad_max={:.3e}",
        other.display(),
        reference.display(),
        difference.vectors,
        difference.sampled,
        difference.potential.l2,
        difference.potential.max,
        difference.gradient.l2,
        difference.gradient.max
    )
}

/// Writes an output file of φ and ∇φ at the sampled targets: `values` as the reference
/// of a problem file, s × m × 4 values (module documentation). The external program
/// writes the same format; this function is its definition and the tests' writer.
///
/// # Errors
///
/// An I/O error of the file.
///
/// # Panics
///
/// If `values.len() != sampled * vectors * 4`.
pub fn write_output(path: &Path, vectors: usize, sampled: usize, values: &[f64]) -> io::Result<()> {
    assert_eq!(values.len(), sampled * vectors * 4, "s × m × 4 values");
    let mut file = BufWriter::new(File::create(path)?);
    file.write_all(&OUTPUT_MAGIC)?;
    for value in [vectors as u64, sampled as u64] {
        file.write_all(&value.to_le_bytes())?;
    }
    write_f64s(&mut file, values)?;
    file.flush()
}

/// The errors of an output against the direct sum, as the `scaling` harness reports them
/// (`nd_fmm_validate::scaling::Errors`): per vector the relative L2 and max errors of φ
/// and of ∇φ (each gradient by its Euclidean norm) over the sampled targets, then the
/// root mean square of each over the vectors.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct OutputErrors {
    /// The charge vectors.
    pub vectors: usize,
    /// The sampled targets.
    pub sampled: usize,
    /// φ.
    pub potential: ErrorNorms,
    /// ∇φ.
    pub gradient: ErrorNorms,
}

/// Measures an output file, or a full output file at the problem's sampled targets,
/// against the reference of its problem file.
///
/// # Errors
///
/// An I/O error, a file that is neither kind of output file, or one whose vectors or
/// targets differ from the problem's (`InvalidData`).
pub fn check_output(problem: &Path, output: &Path) -> io::Result<OutputErrors> {
    let (header, reference) = read_reference(problem)?;
    let mut file = BufReader::new(File::open(output)?);
    let mut magic = [0u8; 8];
    file.read_exact(&mut magic)?;
    if magic == FULL_MAGIC {
        drop(file);
        let (m, n, full) = read_full(output)?;
        if (m, n) != (header.vectors, header.workload.n) {
            return Err(invalid(&format!(
                "the output has {m} vectors at {n} points, the problem {} at {}",
                header.vectors, header.workload.n
            )));
        }
        let sample = read_problem(problem)?.sample;
        let values: Vec<f64> = sample
            .iter()
            .flat_map(|&i| full[i * m * 4..(i + 1) * m * 4].iter().copied())
            .collect();
        return Ok(errors(m, header.sampled, &values, &reference));
    }
    if magic != OUTPUT_MAGIC {
        return Err(invalid("not an output file (its magic is wrong)"));
    }
    let [m, s] = read_u64s::<2>(&mut file)?;
    if (m as usize, s as usize) != (header.vectors, header.sampled) {
        return Err(invalid(&format!(
            "the output has {m} vectors at {s} targets, the problem {} at {}",
            header.vectors, header.sampled
        )));
    }
    let values = read_f64s(&mut file, reference.len())?;
    Ok(errors(header.vectors, header.sampled, &values, &reference))
}

/// The errors of `values` against `reference` (both s × m × 4, module documentation).
pub fn errors(vectors: usize, sampled: usize, values: &[f64], reference: &[f64]) -> OutputErrors {
    let (mut phi_l2, mut phi_max, mut grad_l2, mut grad_max) = (0.0, 0.0, 0.0, 0.0);
    for k in 0..vectors {
        let (mut potential, mut gradient) = (ErrorAccumulator::new(), ErrorAccumulator::new());
        for j in 0..sampled {
            let at = (j * vectors + k) * 4;
            potential.add_values(&values[at..=at], &reference[at..=at]);
            let g = |v: &[f64]| [v[at + 1], v[at + 2], v[at + 3]];
            gradient.add_vectors(&[g(values)], &[g(reference)]);
        }
        let (p, g) = (potential.finish(), gradient.finish());
        phi_l2 += p.l2 * p.l2;
        phi_max += p.max * p.max;
        grad_l2 += g.l2 * g.l2;
        grad_max += g.max * g.max;
    }
    let rms = |sum: f64| (sum / vectors.max(1) as f64).sqrt();
    OutputErrors {
        vectors,
        sampled,
        potential: ErrorNorms {
            l2: rms(phi_l2),
            max: rms(phi_max),
        },
        gradient: ErrorNorms {
            l2: rms(grad_l2),
            max: rms(grad_max),
        },
    }
}

/// The line of `--write-problem` on stdout.
pub fn problem_line(spec: &ProblemSpec, written: &Written) -> String {
    format!(
        "problem: file={} dist={} n={} vectors={} sampled={} seed={:#x} bytes={} \
         reference_threads={} reference_s={:.3}",
        spec.file.display(),
        spec.workload.distribution.name(),
        spec.workload.n,
        spec.vectors,
        spec.sampled.min(spec.workload.n),
        spec.workload.seed,
        written.bytes,
        written.threads,
        written.reference_seconds
    )
}

/// The line of `--check-output` on stdout for one output file: the `key=value` fields of
/// the `scaling` example's summary (`phi_l2`, `phi_max`, `grad_l2`, `grad_max`).
pub fn errors_line(output: &Path, errors: &OutputErrors) -> String {
    format!(
        "errors: file={} vectors={} sampled={} phi_l2={:.3e} phi_max={:.3e} grad_l2={:.3e} \
         grad_max={:.3e}",
        output.display(),
        errors.vectors,
        errors.sampled,
        errors.potential.l2,
        errors.potential.max,
        errors.gradient.l2,
        errors.gradient.max
    )
}

fn invalid(message: &str) -> io::Error {
    io::Error::new(io::ErrorKind::InvalidData, message.to_owned())
}

fn write_f64s(writer: &mut impl Write, values: &[f64]) -> io::Result<()> {
    for value in values {
        writer.write_all(&value.to_le_bytes())?;
    }
    Ok(())
}

fn read_u64s<const K: usize>(reader: &mut impl Read) -> io::Result<[u64; K]> {
    let mut values = [0u64; K];
    let mut bytes = [0u8; 8];
    for value in &mut values {
        reader.read_exact(&mut bytes)?;
        *value = u64::from_le_bytes(bytes);
    }
    Ok(values)
}

fn read_f64s(reader: &mut impl Read, count: usize) -> io::Result<Vec<f64>> {
    let mut values = Vec::with_capacity(count);
    let mut bytes = [0u8; 8];
    for _ in 0..count {
        reader.read_exact(&mut bytes)?;
        values.push(f64::from_le_bytes(bytes));
    }
    Ok(values)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A file in the temporary directory, removed when dropped.
    struct Scratch(PathBuf);

    impl Scratch {
        fn new(name: &str) -> Self {
            Self(std::env::temp_dir().join(format!("nd-fmm-bench-{}-{name}", std::process::id())))
        }
    }

    impl Drop for Scratch {
        fn drop(&mut self) {
            let _ = std::fs::remove_file(&self.0);
        }
    }

    fn spec(file: &Path, distribution: Distribution, threads: usize) -> ProblemSpec {
        ProblemSpec {
            file: file.to_owned(),
            workload: Workload::new(distribution, 300),
            vectors: 3,
            sampled: 17,
            threads: Some(threads),
        }
    }

    #[test]
    fn the_problem_file_holds_the_workload_and_its_direct_sum() {
        let file = Scratch::new("problem.bin");
        let spec = spec(&file.0, Distribution::Plummer, 4);
        let written = write_problem(&spec).unwrap();
        let (n, m, s) = (300u64, 3u64, 17u64);
        assert_eq!(
            written.bytes,
            HEADER_BYTES + 8 * (3 * n + m * n + s + 4 * s * m)
        );

        let mut reader = BufReader::new(File::open(&file.0).unwrap());
        let header = read_header(&mut reader).unwrap();
        assert_eq!(
            header,
            ProblemHeader {
                workload: spec.workload,
                vectors: 3,
                sampled: 17
            }
        );
        let points = read_f64s(&mut reader, 3 * 300).unwrap();
        let charges = read_f64s(&mut reader, 3 * 300).unwrap();
        let sample = read_u64s::<17>(&mut reader).unwrap();
        let workload = spec.workload;
        for i in 0..300 {
            assert_eq!(points[3 * i..3 * i + 3], workload.point(i));
            for k in 0..3 {
                assert_eq!(charges[3 * i + k], workload.charge(k, i));
            }
        }
        let expected: Vec<u64> = workload.sample(17).iter().map(|&i| i as u64).collect();
        assert_eq!(sample[..], expected[..]);

        // The reference: the oracle (the direct sum over every point, divided by 4π).
        let (_, reference) = read_reference(&file.0).unwrap();
        let problem = fmm_accuracy::Problem {
            points: (0..300).map(|i| workload.point(i)).collect(),
            sample: workload.sample(17),
            charges: (0..3)
                .map(|k| (0..300).map(|i| workload.charge(k, i)).collect())
                .collect(),
        };
        let oracle = Oracle::new(&problem, &problem.charges);
        for k in 0..3 {
            for j in 0..17 {
                let at = (j * 3 + k) * 4;
                assert_eq!(reference[at], oracle.potential[k][j]);
                assert_eq!(reference[at + 1..at + 4], oracle.gradient[k][j]);
            }
        }

        // The file does not depend on the threads of the direct sum.
        let one = Scratch::new("problem-1.bin");
        write_problem(&ProblemSpec {
            file: one.0.clone(),
            threads: Some(1),
            ..spec
        })
        .unwrap();
        assert_eq!(
            std::fs::read(&file.0).unwrap(),
            std::fs::read(&one.0).unwrap()
        );
    }

    #[test]
    fn an_output_is_measured_against_the_reference() {
        let problem = Scratch::new("check.bin");
        write_problem(&spec(&problem.0, Distribution::Cube, 2)).unwrap();
        let (header, reference) = read_reference(&problem.0).unwrap();
        let (m, s) = (header.vectors, header.sampled);

        // The reference itself: no error.
        let output = Scratch::new("check.out");
        write_output(&output.0, m, s, &reference).unwrap();
        let exact = check_output(&problem.0, &output.0).unwrap();
        assert_eq!((exact.vectors, exact.sampled), (3, 17));
        assert_eq!(exact.potential, ErrorNorms { l2: 0.0, max: 0.0 });
        assert_eq!(exact.gradient, ErrorNorms { l2: 0.0, max: 0.0 });

        // φ scaled by 1 + 1e-6 and ∇φ by 1 − 2e-6 in every vector: those relative errors.
        let scaled: Vec<f64> = reference
            .iter()
            .enumerate()
            .map(|(i, v)| v * if i % 4 == 0 { 1.0 + 1e-6 } else { 1.0 - 2e-6 })
            .collect();
        write_output(&output.0, m, s, &scaled).unwrap();
        let e = check_output(&problem.0, &output.0).unwrap();
        for (value, expected) in [
            (e.potential.l2, 1e-6),
            (e.potential.max, 1e-6),
            (e.gradient.l2, 2e-6),
            (e.gradient.max, 2e-6),
        ] {
            assert!(
                (value / expected - 1.0).abs() < 1e-6,
                "{value} for {expected}"
            );
        }

        // FMM3D's normalisation up to v2.0.0 (1/r, without 1/(4π)) is off by 4π − 1 in every
        // value.
        let unscaled: Vec<f64> = reference
            .iter()
            .map(|v| v * 4.0 * std::f64::consts::PI)
            .collect();
        write_output(&output.0, m, s, &unscaled).unwrap();
        let e = check_output(&problem.0, &output.0).unwrap();
        assert!((e.potential.l2 - (4.0 * std::f64::consts::PI - 1.0)).abs() < 1e-9);

        // An output of another shape, or not an output, is refused.
        write_output(&output.0, m - 1, s, &reference[..(m - 1) * s * 4]).unwrap();
        let error = check_output(&problem.0, &output.0).unwrap_err();
        assert_eq!(error.kind(), io::ErrorKind::InvalidData);
        let error = check_output(&problem.0, &problem.0).unwrap_err();
        assert!(error.to_string().contains("not an output file"));
        let error = read_reference(&output.0).unwrap_err();
        assert!(error.to_string().contains("not a problem file"));
    }

    #[test]
    fn full_outputs_are_checked_at_the_sample_and_compared_everywhere() {
        let problem = Scratch::new("full.bin");
        write_problem(&spec(&problem.0, Distribution::Cube, 2)).unwrap();
        let data = read_problem(&problem.0).unwrap();
        let workload = data.header.workload;
        assert_eq!(data.points[7], workload.point(7));
        assert_eq!(data.charges[2][5], workload.charge(2, 5));
        assert_eq!(data.sample, workload.sample(17));

        // The direct sum at every point as a full output: exact at the sample.
        let (m, n) = (3, 300);
        let problem_all = fmm_accuracy::Problem {
            points: data.points.clone(),
            sample: (0..n).collect(),
            charges: data.charges.clone(),
        };
        let oracle = Oracle::new(&problem_all, &problem_all.charges);
        let mut exact = vec![0.0; n * m * 4];
        for k in 0..m {
            for i in 0..n {
                let at = (i * m + k) * 4;
                exact[at] = oracle.potential[k][i];
                exact[at + 1..at + 4].copy_from_slice(&oracle.gradient[k][i]);
            }
        }
        let full = Scratch::new("full.out");
        write_full_output(&full.0, m, n, &exact).unwrap();
        let e = check_output(&problem.0, &full.0).unwrap();
        assert_eq!((e.vectors, e.sampled), (3, 17));
        assert_eq!((e.potential.l2, e.gradient.l2), (0.0, 0.0));

        // Another full output, φ off by 1e-6 everywhere: that difference over every point.
        let other: Vec<f64> = exact
            .iter()
            .enumerate()
            .map(|(i, v)| if i % 4 == 0 { v * (1.0 + 1e-6) } else { *v })
            .collect();
        let second = Scratch::new("full-2.out");
        write_full_output(&second.0, m, n, &other).unwrap();
        let d = compare_outputs(&full.0, &second.0).unwrap();
        assert_eq!((d.vectors, d.sampled), (3, 300));
        assert!((d.potential.l2 / 1e-6 - 1.0).abs() < 1e-6);
        assert_eq!(d.gradient.l2, 0.0);
        assert!(difference_line(&full.0, &second.0, &d).starts_with("difference: file="));

        // Shapes must agree, and a sampled output is not a full one.
        let short = Scratch::new("full-3.out");
        write_full_output(&short.0, 1, n, &exact[..n * 4]).unwrap();
        assert_eq!(
            compare_outputs(&full.0, &short.0).unwrap_err().kind(),
            io::ErrorKind::InvalidData
        );
        assert!(check_output(&problem.0, &short.0).is_err());
        let sampled = Scratch::new("sampled.out");
        write_output(&sampled.0, m, 17, &vec![0.0; 17 * m * 4]).unwrap();
        assert!(compare_outputs(&full.0, &sampled.0).is_err());
    }

    #[test]
    fn the_lines_name_every_field() {
        let spec = spec(Path::new("p.bin"), Distribution::Cube, 2);
        let written = Written {
            bytes: 42,
            reference_seconds: 1.5,
            threads: 2,
        };
        assert_eq!(
            problem_line(&spec, &written),
            "problem: file=p.bin dist=cube n=300 vectors=3 sampled=17 seed=0x5ca1e bytes=42 \
             reference_threads=2 reference_s=1.500"
        );
        let errors = OutputErrors {
            vectors: 8,
            sampled: 1000,
            potential: ErrorNorms {
                l2: 1.25e-5,
                max: 3.0e-4,
            },
            gradient: ErrorNorms {
                l2: 2.0e-4,
                max: 1.0e-2,
            },
        };
        assert_eq!(
            errors_line(Path::new("o.out"), &errors),
            "errors: file=o.out vectors=8 sampled=1000 phi_l2=1.250e-5 phi_max=3.000e-4 \
             grad_l2=2.000e-4 grad_max=1.000e-2"
        );
        for d in Distribution::ALL {
            assert_eq!(distribution_of(distribution_code(d)), Some(d));
        }
        assert_eq!(distribution_of(4), None);
    }
}
